package com.volna.inventory_service.service;import com.volna.inventory_service.entity.InventoryRestaurantAccess;import com.volna.inventory_service.exception.ResourceNotFoundException;import com.volna.inventory_service.repository.InventoryRestaurantAccessRepository;import org.springframework.stereotype.Service;import java.util.UUID;@Service public class InventoryRestaurantAccessService{private final InventoryRestaurantAccessRepository repo;public InventoryRestaurantAccessService(InventoryRestaurantAccessRepository r){repo=r;}public UUID restaurant(UUID user){return repo.findByAuthUserId(user).map(InventoryRestaurantAccess::getRestaurantId).orElseThrow(()->new ResourceNotFoundException("Restaurant access not configured for authenticated user"));}}
